use std::env;
use std::process;

mod cli;
mod lang;
mod counter;
mod walker;
mod output;
mod numfmt;

fn main() {
    let args: Vec<String> = env::args().collect();
    match cli::parse(&args) {
        Ok(opts) => {
            process::exit(run(opts));
        }
        Err(e) => {
            e.print();
            process::exit(e.exit_code());
        }
    }
}

fn run(opts: cli::Options) -> i32 {
    if opts.print_help {
        print!("{}", cli::help_text());
        return 0;
    }
    if opts.print_version {
        println!("tokei 14.0.0 compiled with serialization support: json");
        return 0;
    }
    if opts.list_languages {
        print!("{}", lang::list_output());
        return 0;
    }

    // Check for missing input paths
    let inputs = if opts.inputs.is_empty() {
        vec![".".to_string()]
    } else {
        opts.inputs.clone()
    };

    for p in &inputs {
        if !std::path::Path::new(p).exists() {
            eprintln!("Error: '{}' not found.", p);
            return 1;
        }
    }

    output::run_output(&opts, &inputs)
}
