cat > src/cli.rs << 'RUST_EOF'
// CLI argument parsing

#[derive(Debug, Clone, Default)]
pub struct Options {
    pub inputs: Vec<String>,
    pub columns: Option<usize>,
    pub exclude: Vec<String>,
    pub files: bool,
    pub input_file: Option<String>,
    pub hidden: bool,
    pub list_languages: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub output: Option<String>,
    pub streaming: Option<String>,
    pub sort: Option<String>,
    pub rsort: Option<String>,
    pub types: Option<Vec<String>>,
    pub compact: bool,
    pub num_format: Option<String>,
    pub verbose: u8,
    pub print_help: bool,
    pub print_version: bool,
}

pub struct CliError {
    pub msg: String,
    pub code: i32,
    pub to_stderr: bool,
}
impl CliError {
    pub fn print(&self) {
        if self.to_stderr {
            eprint!("{}", self.msg);
        } else {
            print!("{}", self.msg);
        }
    }
    pub fn exit_code(&self) -> i32 { self.code }
}

fn validate_enum(name: &str, val: &str, allowed: &[&str]) -> Result<String, CliError> {
    if allowed.contains(&val) {
        Ok(val.to_string())
    } else {
        let mut msg = String::new();
        msg.push_str(&format!(
            "error: invalid value '{}' for '--{} <{}>'",
            val, name,
            // long name maps to placeholder
            if name == "num-format" { "num_format_style" } else if name == "input" { "file_input" } else if name == "types" { "types" } else { name }
        ));
        if !allowed.is_empty() && name != "output" {
            msg.push_str(&format!("\n  [possible values: {}]", allowed.join(", ")));
        }
        if name == "output" {
            msg.push_str(&format!(": \"{}\" is not a supported serialization format", val));
        }
        msg.push_str("\n\nFor more information, try '--help'.\n");
        Err(CliError { msg, code: 2, to_stderr: true })
    }
}

pub fn parse(args: &[String]) -> Result<Options, CliError> {
    let mut opts = Options::default();
    let mut i = 1;
    let mut positional_only = false;
    while i < args.len() {
        let a = &args[i];
        if positional_only {
            opts.inputs.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            positional_only = true;
            i += 1;
            continue;
        }
        // handle flags
        if a == "-h" || a == "--help" {
            opts.print_help = true;
            i += 1;
            continue;
        }
        if a == "-V" || a == "--version" {
            opts.print_version = true;
            i += 1;
            continue;
        }
        if a == "-l" || a == "--languages" {
            opts.list_languages = true; i += 1; continue;
        }
        if a == "-f" || a == "--files" { opts.files = true; i += 1; continue; }
        if a == "-C" || a == "--compact" { opts.compact = true; i += 1; continue; }
        if a == "--hidden" { opts.hidden = true; i += 1; continue; }
        if a == "--no-ignore" { opts.no_ignore = true; i += 1; continue; }
        if a == "--no-ignore-parent" { opts.no_ignore_parent = true; i += 1; continue; }
        if a == "--no-ignore-dot" { opts.no_ignore_dot = true; i += 1; continue; }
        if a == "--no-ignore-vcs" { opts.no_ignore_vcs = true; i += 1; continue; }
        if a == "-v" || a == "--verbose" { opts.verbose += 1; i += 1; continue; }

        // options with values
        let (key, val_opt): (&str, Option<String>) = if let Some(eq_pos) = a.find('=') {
            (&a[..eq_pos], Some(a[eq_pos+1..].to_string()))
        } else {
            (a.as_str(), None)
        };
        let take_val = |idx: &mut usize| -> Result<String, CliError> {
            if let Some(v) = &val_opt {
                Ok(v.clone())
            } else {
                *idx += 1;
                if *idx >= args.len() {
                    return Err(CliError{
                        msg: format!("error: a value is required for '{}'\n\nFor more information, try '--help'.\n", key),
                        code: 2, to_stderr: true
                    });
                }
                Ok(args[*idx].clone())
            }
        };
        match key {
            "-c" | "--columns" => {
                let v = take_val(&mut i)?;
                match v.parse::<usize>() {
                    Ok(n) => opts.columns = Some(n),
                    Err(_) => return Err(CliError{
                        msg: format!("error: invalid value '{}' for '--columns <columns>': invalid digit found in string\n\nFor more information, try '--help'.\n", v),
                        code: 2, to_stderr: true
                    })
                }
            }
            "-e" | "--exclude" => {
                let v = take_val(&mut i)?;
                opts.exclude.push(v);
            }
            "-i" | "--input" => {
                let v = take_val(&mut i)?;
                opts.input_file = Some(v);
            }
            "-o" | "--output" => {
                let v = take_val(&mut i)?;
                let valid = validate_enum("output", &v, &["cbor", "json", "yaml"])?;
                opts.output = Some(valid);
            }
            "--streaming" => {
                let v = take_val(&mut i)?;
                let valid = validate_enum("streaming", &v, &["simple", "json"])?;
                opts.streaming = Some(valid);
            }
            "-s" | "--sort" => {
                let v = take_val(&mut i)?;
                let valid = validate_enum("sort", &v, &["files", "lines", "blanks", "code", "comments"])?;
                opts.sort = Some(valid);
            }
            "-r" | "--rsort" => {
                let v = take_val(&mut i)?;
                let valid = validate_enum("rsort", &v, &["files", "lines", "blanks", "code", "comments"])?;
                opts.rsort = Some(valid);
            }
            "-t" | "--types" => {
                let v = take_val(&mut i)?;
                opts.types = Some(v.split(',').map(|s| s.trim().to_lowercase()).collect());
            }
            "-n" | "--num-format" => {
                let v = take_val(&mut i)?;
                let valid = validate_enum("num-format", &v, &["commas", "dots", "plain", "underscores"])?;
                opts.num_format = Some(valid);
            }
            _ => {
                if a.starts_with('-') && a != "-" {
                    return Err(CliError {
                        msg: format!("error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: executable [OPTIONS] [input]...\n\nFor more information, try '--help'.\n", a, a, a),
                        code: 2, to_stderr: true
                    });
                }
                opts.inputs.push(a.clone());
            }
        }
        i += 1;
    }
    Ok(opts)
}

pub fn help_text() -> String {
    r#"Count your code, quickly.
Support this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky

Usage: executable [OPTIONS] [input]...

Arguments:
  [input]...  The path(s) to the file or directory to be counted. (default current directory)

Options:
  -c, --columns <columns>              Sets a strict column width of the output, only available for
                                       terminal output.
  -e, --exclude <exclude>              Ignore all files & directories matching the pattern.
  -f, --files                          Will print out statistics on individual files.
  -i, --input <file_input>             Gives statistics from a previous tokei run. Can be given a
                                       file path, or "stdin" to read from stdin.
      --hidden                         Count hidden files.
  -l, --languages                      Prints out supported languages and their extensions.
      --no-ignore                      Don't respect ignore files (.gitignore, .ignore, etc.). This
                                       implies --no-ignore-parent, --no-ignore-dot, and
                                       --no-ignore-vcs.
      --no-ignore-parent               Don't respect ignore files (.gitignore, .ignore, etc.) in
                                       parent directories.
      --no-ignore-dot                  Don't respect .ignore and .tokeignore files, including those
                                       in parent directories.
      --no-ignore-vcs                  Don't respect VCS ignore files (.gitignore, .hgignore, etc.)
                                       including those in parent directories.
  -o, --output <output>                Outputs Tokei in a specific format. Compile with additional
                                       features for more format support.
      --streaming <streaming>          prints the (language, path, lines, blanks, code, comments)
                                       records as simple lines or as Json for batch processing
                                       [possible values: simple, json]
  -s, --sort <sort>                    Sort languages based on column [possible values: files,
                                       lines, blanks, code, comments]
  -r, --rsort <rsort>                  Reverse sort languages based on column [possible values:
                                       files, lines, blanks, code, comments]
  -t, --types <types>                  Filters output by language type, separated by a comma. i.e.
                                       -t=Rust,Markdown
  -C, --compact                        Do not print statistics about embedded languages.
  -n, --num-format <num_format_style>  Format of printed numbers, i.e., plain (1234, default),
                                       commas (1,234), dots (1.234), or underscores (1_234). Cannot
                                       be used with --output. [possible values: commas, dots, plain,
                                       underscores]
  -v, --verbose...                     Set log output level:
                                                               1: to show unknown file extensions,
                                                               2: reserved for future debugging,
                                                               3: enable file level trace. Not
                                                               recommended on multiple files
  -h, --help                           Print help
  -V, --version                        Print version
"#.to_string()
}
RUST_EOF
echo "cli.rs written"

