pub fn format(n: u64, style: Option<&str>) -> String {
    let s = n.to_string();
    match style {
        Some("commas") => sep(&s, ','),
        Some("dots") => sep(&s, '.'),
        Some("underscores") => sep(&s, '_'),
        _ => s,
    }
}
fn sep(s: &str, ch: char) -> String {
    let bytes: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let n = bytes.len();
    for (i, c) in bytes.iter().enumerate() {
        let from_end = n - i - 1;
        out.push(*c);
        if from_end > 0 && from_end % 3 == 0 { out.push(ch); }
    }
    out
}
