pub fn find_by_path(path: &std::path::Path) -> Option<&'static Lang> {
    let filename_raw = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
    // Check filename match (case-sensitive)
    for l in LANGS {
        for fn_name in l.filenames {
            if filename_raw == *fn_name { return Some(l); }
        }
    }
    // Check extension (lowercase)
    let filename_lower = filename_raw.to_ascii_lowercase();
    // Special-case: dotfiles. If filename starts with '.', compare full name as extension
    let ext_from_dot = if filename_lower.starts_with('.') {
        Some(&filename_lower[1..])
    } else { None };
    let ext = path.extension().and_then(|s| s.to_str()).map(|s| s.to_ascii_lowercase());
    for l in LANGS {
        for e in l.extensions {
            if let Some(ref x) = ext {
                if x == e { return Some(l); }
            }
            if let Some(edot) = ext_from_dot {
                if edot == *e { return Some(l); }
            }
            // Also check if full filename matches an extension (case where lang uses no extension)
            if filename_lower == *e { return Some(l); }
        }
    }
    None
}

