// Line counter for a single file
use crate::lang::Lang;

#[derive(Debug, Default, Clone)]
pub struct Stats {
    pub blanks: u64,
    pub code: u64,
    pub comments: u64,
}
impl Stats {
    pub fn lines(&self) -> u64 { self.blanks + self.code + self.comments }
    pub fn add(&mut self, other: &Stats) {
        self.blanks += other.blanks;
        self.code += other.code;
        self.comments += other.comments;
    }
}

pub fn count_text(text: &str, lang: &Lang) -> Stats {
    let mut s = Stats::default();
    // Normalize line endings: split on \n and strip optional trailing \r
    let raw_lines: Vec<&str> = text.split('\n').collect();
    let n = raw_lines.len();
    // If the text doesn't end with '\n', split gives an extra "trailing" line of real content.
    // If it ends with '\n', split gives an empty last element we should not count.
    let ends_with_nl = text.ends_with('\n');
    let iter_count = if ends_with_nl && n > 0 && raw_lines[n-1].is_empty() { n - 1 } else { n };

    // State across lines (block comment depth or doc quote)
    let mut block_stack: Vec<&str> = Vec::new(); // stack of closing delimiters
    let mut in_doc_quote: Option<&str> = None; // doc quote close delimiter

    for i in 0..iter_count {
        let mut line = raw_lines[i];
        if line.ends_with('\r') { line = &line[..line.len()-1]; }
        let trimmed = line.trim();
        if trimmed.is_empty() && block_stack.is_empty() && in_doc_quote.is_none() {
            s.blanks += 1;
            continue;
        }
        let (had_code, new_block_stack, new_doc_quote) = classify_line(trimmed, lang, block_stack.clone(), in_doc_quote);
        block_stack = new_block_stack;
        in_doc_quote = new_doc_quote;
        if had_code { s.code += 1; } else { s.comments += 1; }
    }
    s
}

// Return (had_code_on_line, new_block_stack, new_doc_quote)
fn classify_line<'a>(
    line: &'a str,
    lang: &'a Lang,
    mut block_stack: Vec<&'static str>,
    mut doc_quote: Option<&'static str>,
) -> (bool, Vec<&'static str>, Option<&'static str>) {
    // Walk char-by-char (byte by byte since delimiters are ASCII)
    let bytes = line.as_bytes();
    let mut i = 0;
    let mut had_code = false;
    let mut in_string: Option<&'static str> = None;
    while i < bytes.len() {
        // Inside doc quote (spans lines)
        if let Some(close) = doc_quote {
            if bytes_starts_with(bytes, i, close.as_bytes()) {
                i += close.len();
                doc_quote = None;
                continue;
            }
            i += 1;
            continue;
        }
        // Inside block comment (spans lines)
        if let Some(top_close) = block_stack.last().copied() {
            // Check nested block comment open if nested is allowed
            if lang.nested {
                let mut opened = false;
                for (open, close) in lang.multi_line {
                    if bytes_starts_with(bytes, i, open.as_bytes()) {
                        block_stack.push(close);
                        i += open.len();
                        opened = true;
                        break;
                    }
                }
                if opened { continue; }
            }
            if bytes_starts_with(bytes, i, top_close.as_bytes()) {
                block_stack.pop();
                i += top_close.len();
                continue;
            }
            i += 1;
            continue;
        }
        // Inside string (single-line)
        if let Some(close) = in_string {
            if bytes[i] == b'\\' && i + 1 < bytes.len() {
                i += 2; continue;
            }
            if bytes_starts_with(bytes, i, close.as_bytes()) {
                i += close.len();
                in_string = None;
                continue;
            }
            i += 1;
            continue;
        }
        // Not in comment/string. Check for comment starts.
        // Line comment at this position => rest of line is comment
        for lc in lang.line_comments {
            if bytes_starts_with(bytes, i, lc.as_bytes()) {
                // The rest of the line is comment. If nothing before was code, line is comment.
                return (had_code, block_stack, doc_quote);
            }
        }
        // Block comment start
        let mut opened = false;
        for (open, close) in lang.multi_line {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                block_stack.push(close);
                i += open.len();
                opened = true;
                break;
            }
        }
        if opened { continue; }
        // Doc quote
        let mut dqopen = false;
        for (open, close) in lang.doc_quotes {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                // If whole line is just docstring, count as comment. Here we just mark if not had_code.
                // Doc quote after code is treated as code (string)
                if had_code {
                    // treat as string
                    in_string = Some(close);
                } else {
                    doc_quote = Some(close);
                }
                i += open.len();
                dqopen = true;
                break;
            }
        }
        if dqopen { continue; }
        // String start
        let mut stopen = false;
        for (open, close) in lang.quotes {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                in_string = Some(close);
                had_code = true;
                i += open.len();
                stopen = true;
                break;
            }
        }
        if stopen { continue; }
        // Other character
        if !bytes[i].is_ascii_whitespace() {
            had_code = true;
        }
        i += 1;
    }
    (had_code, block_stack, doc_quote)
}

