// Walk directories collecting files to count.
use std::path::{Path, PathBuf};
use std::collections::HashSet;
use std::fs;

#[derive(Debug, Default, Clone)]
pub struct WalkOpts {
    pub hidden: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub excludes: Vec<String>,
}

pub fn walk(roots: &[String], opts: &WalkOpts) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for r in roots {
        let p = PathBuf::from(r);
        if p.is_file() {
            if !seen.contains(&p) {
                seen.insert(p.clone());
                out.push(p);
            }
        } else if p.is_dir() {
            // Collect effective ignore patterns
            let mut ignore = GitIgnore::new(opts.excludes.clone());
            if !opts.no_ignore {
                // load .gitignore etc. from root and recurse into dirs
            }
            walk_dir(&p, &mut ignore, opts, &mut out, &mut seen);
        }
    }
    out.sort();
    out
}

fn walk_dir(dir: &Path, ignore: &mut GitIgnore, opts: &WalkOpts, out: &mut Vec<PathBuf>, seen: &mut HashSet<PathBuf>) {
    // Load ignore files from this directory
    let added = if !opts.no_ignore {
        load_ignores(dir, opts, ignore)
    } else { 0 };
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => { ignore.pop(added); return; }
    };
    let mut paths: Vec<PathBuf> = entries.filter_map(|e| e.ok().map(|e| e.path())).collect();
    paths.sort();
    for path in paths {
        let name = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
        // Hidden files
        if !opts.hidden && name.starts_with('.') && name != "." && name != ".." {
            continue;
        }
        // Always skip .git directory in practice
        if name == ".git" { continue; }
        let is_dir = path.is_dir();
        let rel = path.strip_prefix(dir).unwrap_or(&path).to_string_lossy().to_string();
        if ignore.is_ignored(&rel, is_dir) {
            continue;
        }
        if is_dir {
            walk_dir(&path, ignore, opts, out, seen);
        } else if path.is_file() {
            if !seen.contains(&path) {
                seen.insert(path.clone());
                out.push(path);
            }
        }
    }
    ignore.pop(added);
}

fn load_ignores(dir: &Path, opts: &WalkOpts, ignore: &mut GitIgnore) -> usize {
    let mut added = 0;
    let candidates: Vec<&str> = {
        let mut v = Vec::new();
        if !opts.no_ignore_vcs { v.push(".gitignore"); }
        if !opts.no_ignore_dot { v.push(".ignore"); v.push(".tokeignore"); }
        v
    };
    for name in candidates {
        let p = dir.join(name);
        if let Ok(data) = fs::read_to_string(&p) {
            for line in data.lines() {
                let l = line.trim();
                if l.is_empty() || l.starts_with('#') { continue; }
                ignore.push(l.to_string());
                added += 1;
            }
        }
    }
    added
}

pub struct GitIgnore {
    patterns: Vec<String>, // stack
}
impl GitIgnore {
    pub fn new(excludes: Vec<String>) -> Self {
        GitIgnore { patterns: excludes }
    }
    pub fn push(&mut self, p: String) { self.patterns.push(p); }
    pub fn pop(&mut self, n: usize) { for _ in 0..n { self.patterns.pop(); } }
    pub fn is_ignored(&self, name: &str, _is_dir: bool) -> bool {
        // Simple pattern matching. Last rule wins; negations with !.
        let mut ignored = false;
        for raw in &self.patterns {
            let (neg, pat) = if let Some(rest) = raw.strip_prefix('!') {
                (true, rest.to_string())
            } else { (false, raw.clone()) };
            if matches_glob(&pat, name) {
                ignored = !neg;
            }
        }
        ignored
    }
}

fn matches_glob(pat: &str, name: &str) -> bool {
    // Support: *, **, ?, trailing /
    let pat = pat.trim_end_matches('/');
    // If pattern contains '/', match full relative path; else match basename or any segment
    if !pat.contains('/') {
        // Match any path component
        let bname = std::path::Path::new(name).file_name()
            .and_then(|s| s.to_str()).unwrap_or(name);
        glob_match(pat, bname) || glob_match(pat, name)
    } else {
        glob_match(pat, name)
    }
}

fn glob_match(pat: &str, s: &str) -> bool {
    // Greedy glob-like matching with * and ?
    let p = pat.as_bytes();
    let t = s.as_bytes();
    glob_rec(p, 0, t, 0)
}
fn glob_rec(p: &[u8], pi: usize, t: &[u8], ti: usize) -> bool {
    if pi == p.len() { return ti == t.len(); }
    let c = p[pi];
    if c == b'*' {
        // Consume consecutive '*'
        let mut j = pi;
        while j < p.len() && p[j] == b'*' { j += 1; }
        if j == p.len() { return true; }
        // Try all positions
        for k in ti..=t.len() {
            if glob_rec(p, j, t, k) { return true; }
        }
        false
    } else if c == b'?' {
        if ti >= t.len() { return false; }
        glob_rec(p, pi+1, t, ti+1)
    } else {
        if ti >= t.len() { return false; }
        if t[ti] != c { return false; }
        glob_rec(p, pi+1, t, ti+1)
    }
}
