        if j == p.len() { return true; }
        // Try all positions
        for k in ti..=t.len() {
            if glob_rec(p, j, t, k) { return true; }
        }
        false
    } else if c == b'?' {
        if ti >= t.len() { return false; }
        glob_rec(p, pi+1, t, ti+1)
    } else {
        if ti >= t.len() { return false; }
        if t[ti] != c { return false; }
        glob_rec(p, pi+1, t, ti+1)
    }
