use crate::cli::Options;
use crate::counter::{self, Stats};
use crate::lang::{self, Lang};
use crate::numfmt;
use crate::walker::{self, WalkOpts};
use std::collections::BTreeMap;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct FileReport {
    pub name: String,
    pub stats: Stats,
}

#[derive(Debug, Default, Clone)]
pub struct LanguageStats {
    pub stats: Stats,
    pub reports: Vec<FileReport>,
    // embedded: lang_key -> files
    pub children: BTreeMap<String, Vec<FileReport>>,
    pub inaccurate: bool,
}
impl LanguageStats {
    pub fn total_lines(&self) -> u64 {
        let mut t = self.stats.clone();
        for (_k, v) in &self.children {
            for r in v { t.add(&r.stats); }
        }
        t.lines()
    }
    pub fn add_child(&mut self, kind: &str, r: FileReport) {
        self.children.entry(kind.to_string()).or_default().push(r);
    }
}

pub fn run_output(opts: &Options, inputs: &[String]) -> i32 {
    // Walk files
    let walk_opts = WalkOpts {
        hidden: opts.hidden,
        no_ignore: opts.no_ignore,
        no_ignore_parent: opts.no_ignore_parent,
        no_ignore_dot: opts.no_ignore_dot,
        no_ignore_vcs: opts.no_ignore_vcs,
        excludes: opts.exclude.clone(),
    };
    let files = walker::walk(inputs, &walk_opts);

    // Map: lang_key -> LanguageStats
    let mut lang_stats: BTreeMap<String, LanguageStats> = BTreeMap::new();
    for f in &files {
        if let Some((lang_key, report)) = count_file(f) {
            let entry = lang_stats.entry(lang_key.to_string()).or_default();
            entry.stats.add(&report.stats);
            entry.reports.push(report);
        }
    }

    // Type filter
    if let Some(ts) = &opts.types {
        let keep: Vec<String> = lang_stats.keys()
            .filter(|k| ts.iter().any(|t| *t == k.to_ascii_lowercase() || {
                if let Some(l) = lang_by_key(k) { l.name.to_ascii_lowercase() == *t } else { false }
            })).cloned().collect();
        lang_stats.retain(|k, _| keep.contains(k));
    }

    // Handle streaming
    if let Some(mode) = &opts.streaming {
        return stream_output(mode, &lang_stats);
    }
    // Handle JSON output
    if let Some(fmt) = &opts.output {
        return format_output(fmt, &lang_stats);
    }

    // Table output
    print_table(opts, &lang_stats);
    0
}

fn lang_by_key(k: &str) -> Option<&'static Lang> {
    for l in crate::lang::LANGS {
        if l.key == k { return Some(l); }
    }
    None
}

fn count_file(path: &PathBuf) -> Option<(String, FileReport)> {
    let lang = lang::find_by_path(path)?;
    let text = match std::fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return None,
    };
    let stats = counter::count_text(&text, lang);
    let report = FileReport {
        name: path.display().to_string(),
        stats,
    };
    Some((lang.key.to_string(), report))
}

// ----- Table output -----

const NUM_WIDTH: usize = 13;
const N_NUM_COLS: usize = 5;

fn term_width(opts: &Options) -> usize {
    let minimum = 81;
    let w = opts.columns.unwrap_or(81);
    if w < minimum { minimum } else { w }
}

fn bar(ch: &str, width: usize) -> String {
    ch.repeat(width)
}

fn print_table(opts: &Options, lang_stats: &BTreeMap<String, LanguageStats>) {
    let width = term_width(opts);
    let bar_heavy = bar("━", width);
    let bar_light = bar("─", width);
    println!("{}", bar_heavy);
    println!("{}", header_row(width));
    println!("{}", bar_heavy);

    // Sort languages
    let mut ordered: Vec<(&String, &LanguageStats)> = lang_stats.iter().collect();
    apply_sort(&mut ordered, opts);

    // Split into "simple" languages (no children) and "embedded" (with children)
    let has_any_children = ordered.iter().any(|(_, v)| !v.children.is_empty());
    if has_any_children {
        let mut first_group: Vec<(&String, &LanguageStats)> = Vec::new();
        let mut second_group: Vec<(&String, &LanguageStats)> = Vec::new();
        for (k, v) in &ordered {
            if v.children.is_empty() {
                first_group.push((*k, *v));
            } else {
                second_group.push((*k, *v));
            }
        }
        for (k, v) in &first_group {
            print_lang_row(k, v, width, opts);
            if opts.files {
                println!("{}", bar_light);
                for r in &v.reports {
                    print_file_row(&r.name, &r.stats, width, opts);
                }
                println!("{}", bar_light);
            }
        }
        if !second_group.is_empty() {
            println!("{}", bar_light);
            for (k, v) in &second_group {
                print_lang_row(k, v, width, opts);
                if !opts.compact {
                    for (ck, cf) in &v.children {
                        // aggregate stats for child
                        let mut cstats = Stats::default();
                        for r in cf { cstats.add(&r.stats); }
                        let pipe_name = format!("|- {}", name_of(ck));
                        print_row_with_files(&pipe_name, cf.len() as u64, &cstats, width, opts);
                    }
                    // Total line
                    let mut total = v.stats.clone();
                    let mut _files = v.reports.len() as u64;
                    for (_ck, cf) in &v.children {
                        for r in cf { total.add(&r.stats); _files += 1; }
                    }
                    print_total_row("(Total)", &total, width, opts);
                }
            }
        }
    } else {
        for (k, v) in &ordered {
            print_lang_row(k, v, width, opts);
            if opts.files {
                println!("{}", bar_light);
                for r in &v.reports {
                    print_file_row(&r.name, &r.stats, width, opts);
                }
                println!("{}", bar_light);
            }
        }
    }

    println!("{}", bar_heavy);
    // Total row
    let mut total = Stats::default();
    let mut total_files: u64 = 0;
    for (_k, v) in &ordered {
        total.add(&v.stats);
        total_files += v.reports.len() as u64;
        for (_, cf) in &v.children {
            for r in cf { total.add(&r.stats); }
        }
    }
    print_total_files_row("Total", total_files, &total, width, opts);
    println!("{}", bar_heavy);
}

fn apply_sort(ordered: &mut Vec<(&String, &LanguageStats)>, opts: &Options) {
    // Default sort: by display name, alphabetical
    ordered.sort_by(|a, b| {
        let an = name_of(a.0);
        let bn = name_of(b.0);
        an.cmp(&bn)
    });
    if let Some(col) = opts.sort.as_deref().or(opts.rsort.as_deref()) {
        ordered.sort_by(|a, b| {
            let av = column_val(col, a.1);
            let bv = column_val(col, b.1);
            bv.cmp(&av) // descending
        });
    }
    if opts.rsort.is_some() {
        ordered.reverse();
    }
}

fn column_val(col: &str, s: &LanguageStats) -> u64 {
    match col {
        "files" => s.reports.len() as u64,
        "lines" => s.total_lines(),
        "code" => s.stats.code,
        "comments" => s.stats.comments,
        "blanks" => s.stats.blanks,
        _ => 0,
    }
}

fn name_of(k: &str) -> String {
    if let Some(l) = lang_by_key(k) { return l.name.to_string(); }
    k.to_string()
}

fn header_row(width: usize) -> String {
    // Content width = width - 1
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut s = String::new();
    s.push(' ');
    s.push_str(&pad_right("Language", name_w - 1));
