            for r in cf { total.add(&r.stats); }
        }
    }
    print_total_files_row("Total", total_files, &total, width, opts);
    println!("{}", bar_heavy);
}

fn apply_sort(ordered: &mut Vec<(&String, &LanguageStats)>, opts: &Options) {
    // Default sort: by display name, alphabetical
    ordered.sort_by(|a, b| {
        let an = name_of(a.0);
        let bn = name_of(b.0);
        an.cmp(&bn)
    });
    if let Some(col) = opts.sort.as_deref().or(opts.rsort.as_deref()) {
        ordered.sort_by(|a, b| {
            let av = column_val(col, a.1);
            let bv = column_val(col, b.1);
            bv.cmp(&av) // descending
        });
    }
    if opts.rsort.is_some() {
        ordered.reverse();
    }
}

fn column_val(col: &str, s: &LanguageStats) -> u64 {
    match col {
        "files" => s.reports.len() as u64,
        "lines" => s.total_lines(),
        "code" => s.stats.code,
        "comments" => s.stats.comments,
        "blanks" => s.stats.blanks,
        _ => 0,
    }
}

fn name_of(k: &str) -> String {
    if let Some(l) = lang_by_key(k) { return l.name.to_string(); }
    k.to_string()
}

fn header_row(width: usize) -> String {
    // Content width = width - 1
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut s = String::new();
    s.push(' ');
    s.push_str(&pad_right("Language", name_w - 1));
    s.push_str(&pad_left_width("Files", NUM_WIDTH));
    s.push_str(&pad_left_width("Lines", NUM_WIDTH));
    s.push_str(&pad_left_width("Code", NUM_WIDTH));
    s.push_str(&pad_left_width("Comments", NUM_WIDTH));
    s.push_str(&pad_left_width("Blanks", NUM_WIDTH));
    s
}

fn pad_right(s: &str, w: usize) -> String {
    let c: Vec<char> = s.chars().collect();
    if c.len() >= w { return s.to_string(); }
    let mut r = String::from(s);
    for _ in c.len()..w { r.push(' '); }
    r
}
fn pad_left_width(s: &str, w: usize) -> String {
    let n = s.chars().count();
    let mut r = String::new();
    if n < w { for _ in n..w { r.push(' '); } }
    r.push_str(s);
    r
}

fn format_num(n: u64, opts: &Options) -> String {
    numfmt::format(n, opts.num_format.as_deref())
}

fn print_lang_row(k: &str, v: &LanguageStats, width: usize, opts: &Options) {
    let name = name_of(k);
    let files = v.reports.len() as u64;
    print_row_with_files(&name, files, &v.stats, width, opts);
}

fn print_row_with_files(name: &str, files: u64, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut out = String::new();
    out.push(' ');
    let name_display = truncate_to(name, name_w - 1);
    out.push_str(&pad_right(&name_display, name_w - 1));
    out.push_str(&pad_left_width(&format_num(files, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn print_file_row(name: &str, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut out = String::new();
    out.push(' ');
    let mut d = name.to_string();
    let max_name_display = (name_w - 1) + NUM_WIDTH; // File name area extends into files column
    if d.chars().count() > max_name_display {
        // truncate from the left (keep tail of path)
        let chars: Vec<char> = d.chars().collect();
        let start = chars.len() - (max_name_display - 1);
        d = format!("|{}", chars[start..].iter().collect::<String>());
    }
    out.push_str(&pad_right(&d, name_w - 1 + NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn print_total_row(label: &str, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut out = String::new();
    out.push(' ');
    out.push_str(&pad_right(label, name_w - 1 + NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn print_total_files_row(label: &str, files: u64, s: &Stats, width: usize, opts: &Options) {
    print_row_with_files(label, files, s, width, opts);
}

fn truncate_to(s: &str, w: usize) -> String {
    let c: Vec<char> = s.chars().collect();
    if c.len() <= w { return s.to_string(); }
    c.iter().take(w).collect()
}

// ----- JSON output -----

fn format_output(fmt: &str, lang_stats: &BTreeMap<String, LanguageStats>) -> i32 {
    if fmt == "json" {
        print!("{}", json_output(lang_stats));
        return 0;
    }
    // Other formats unsupported in this build
    eprintln!("error: format {} not compiled in", fmt);
    1
}

fn json_output(lang_stats: &BTreeMap<String, LanguageStats>) -> String {
    let mut s = String::new();
    s.push('{');
    let mut first = true;
    let mut total = LanguageStats::default();
    for (k, v) in lang_stats {
        if !first { s.push(','); } first = false;
        s.push('"'); s.push_str(&json_escape(&name_of(k))); s.push('"'); s.push(':');
        s.push_str(&json_lang_stats(v));
        // Accumulate total
        total.stats.add(&v.stats);
        for r in &v.reports {
            total.add_child(k, r.clone());
        }
    }
    if !first { s.push(','); }
    s.push_str("\"Total\":");
    s.push_str(&json_lang_stats(&total));
    s.push('}');
    s
}

fn json_lang_stats(v: &LanguageStats) -> String {
    let mut s = String::new();
    s.push('{');
    s.push_str(&format!("\"blanks\":{},\"code\":{},\"comments\":{}", v.stats.blanks, v.stats.code, v.stats.comments));
    s.push_str(",\"reports\":[");
    for (i, r) in v.reports.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&json_report(r));
    }
    s.push_str("],\"children\":{");
    let mut first = true;
    for (ck, cf) in &v.children {
        if !first { s.push(','); } first = false;
        s.push('"'); s.push_str(&json_escape(&name_of(ck))); s.push('"'); s.push(':'); s.push('[');
        for (i, r) in cf.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&json_report(r));
        }
        s.push(']');
    }
    s.push_str("},\"inaccurate\":false}");
    s
}

fn json_report(r: &FileReport) -> String {
    format!(
        "{{\"stats\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{}}}},\"name\":\"{}\"}}",
        r.stats.blanks, r.stats.code, r.stats.comments, json_escape(&r.name)
    )
}

fn json_escape(s: &str) -> String {
    let mut r = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

fn stream_output(mode: &str, lang_stats: &BTreeMap<String, LanguageStats>) -> i32 {
    // Streaming header (only for simple mode)
    if mode == "simple" {
        println!("# language                                        path                                          lines         code       comments      blanks   ");
        println!("########## ################################################################################ ############ ############ ############ ############");
    }
    // Output per-file entries grouped by language
    // In observed behavior: iter order was Rust, Python (not alphabetical?) — appears to be insertion order.
    // We'll use alphabetical by language name for determinism, matching observed alphabetical order.
    let keys: Vec<&String> = lang_stats.keys().collect();
    for k in keys {
        let ls = &lang_stats[k];
        let name = name_of(k);
        for r in &ls.reports {
            if mode == "simple" {
                println!(
                    "{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}",
                    name, r.name, r.stats.lines(), r.stats.code, r.stats.comments, r.stats.blanks
                );
            } else {
                // json line
                println!(
                    "{{\"language\":\"{}\",\"stats\":{{\"name\":\"{}\",\"stats\":{{\"blanks\":{},\"blobs\":{{}},\"code\":{},\"comments\":{}}}}}}}",
                    json_escape(&name), json_escape(&r.name), r.stats.blanks, r.stats.code, r.stats.comments
                );
            }
        }
    }
    0
}
