use crate::cli::Options;
use crate::counter::{self, Stats};
use crate::lang::{self, Lang};
use crate::numfmt;
use crate::walker::{self, WalkOpts};
use std::collections::BTreeMap;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct FileReport {
    pub name: String,
    pub stats: Stats,
}

#[derive(Debug, Default, Clone)]
pub struct LanguageStats {
    pub stats: Stats,
    pub reports: Vec<FileReport>,
    pub children: BTreeMap<String, Vec<FileReport>>,
    pub inaccurate: bool,
}
impl LanguageStats {
    pub fn files(&self) -> u64 { self.reports.len() as u64 }
    pub fn total_stats(&self) -> Stats {
        let mut t = self.stats.clone();
        for (_k, v) in &self.children {
            for r in v { t.add(&r.stats); }
        }
        t
    }
}

pub fn run_output(opts: &Options, inputs: &[String]) -> i32 {
    let walk_opts = WalkOpts {
        hidden: opts.hidden,
        no_ignore: opts.no_ignore,
        no_ignore_parent: opts.no_ignore_parent,
        no_ignore_dot: opts.no_ignore_dot,
        no_ignore_vcs: opts.no_ignore_vcs,
        excludes: opts.exclude.clone(),
    };
    let files = walker::walk(inputs, &walk_opts);

    let mut lang_stats: BTreeMap<String, LanguageStats> = BTreeMap::new();
    for f in &files {
        if let Some((lang_key, report, embedded)) = count_file(f) {
            let entry = lang_stats.entry(lang_key.clone()).or_default();
            entry.stats.add(&report.stats);
            entry.reports.push(report.clone());
            for (ek, es) in embedded {
                let ce = entry.children.entry(ek).or_default();
                ce.push(FileReport { name: report.name.clone(), stats: es });
            }
        }
    }

    if let Some(ts) = &opts.types {
        let keep: Vec<String> = lang_stats.keys()
            .filter(|k| ts.iter().any(|t| *t == k.to_ascii_lowercase() || {
                if let Some(l) = lang_by_key(k) { l.name.to_ascii_lowercase() == *t } else { false }
            })).cloned().collect();
        lang_stats.retain(|k, _| keep.contains(k));
    }

    if let Some(mode) = &opts.streaming {
        return stream_output(mode, &lang_stats);
    }
    if let Some(fmt) = &opts.output {
        return format_output(fmt, &lang_stats);
    }

    print_table(opts, &lang_stats);
    0
}

fn lang_by_key(k: &str) -> Option<&'static Lang> {
    for l in crate::lang::LANGS {
        if l.key == k { return Some(l); }
    }
    None
}

fn count_file(path: &PathBuf) -> Option<(String, FileReport, BTreeMap<String, Stats>)> {
    let lang = lang::find_by_path(path)?;
    let text = match std::fs::read_to_string(path) {
        Ok(t) => t,
        Err(_) => return None,
    };
    let cr = counter::count_text(&text, lang);
    let report = FileReport {
        name: path.display().to_string(),
        stats: cr.stats,
    };
    Some((lang.key.to_string(), report, cr.embedded))
}

const NUM_WIDTH: usize = 13;
const N_NUM_COLS: usize = 5;

fn term_width(opts: &Options) -> usize {
    let minimum = 81;
    let w = opts.columns.unwrap_or(81);
    if w < minimum { minimum } else { w }
}

fn bar(ch: &str, width: usize) -> String {
    ch.repeat(width)
}

fn print_table(opts: &Options, lang_stats: &BTreeMap<String, LanguageStats>) {
    let width = term_width(opts);
    let bar_heavy = bar("━", width);
    let bar_light = bar("─", width);
    println!("{}", bar_heavy);
    println!("{}", header_row(width));
    println!("{}", bar_heavy);

    let mut ordered: Vec<(String, LanguageStats)> = lang_stats.iter().map(|(k,v)| (k.clone(), v.clone())).collect();
    apply_sort(&mut ordered, opts);

    let has_any_children = ordered.iter().any(|(_, v)| !v.children.is_empty());
    let compact = opts.compact;
    if has_any_children && !compact {
        let mut first_group: Vec<&(String, LanguageStats)> = Vec::new();
        let mut second_group: Vec<&(String, LanguageStats)> = Vec::new();
        for kv in &ordered {
            if kv.1.children.is_empty() { first_group.push(kv); } else { second_group.push(kv); }
        }
        for (k, v) in &first_group {
            print_lang_row(k, v, width, opts);
            if opts.files {
                println!("{}", bar_light);
                for r in &v.reports {
                    print_file_row(&r.name, &r.stats, width, opts);
                }
                println!("{}", bar_light);
            }
        }
        if !second_group.is_empty() {
            println!("{}", bar_light);
            for (k, v) in &second_group {
                print_lang_row(k, v, width, opts);
                if opts.files {
                    println!("{}", bar_light);
                    for r in &v.reports {
                        print_file_row(&r.name, &r.stats, width, opts);
                    }
                    println!("{}", bar_light);
                }
                for (ck, cf) in &v.children {
                    let mut cstats = Stats::default();
                    for r in cf { cstats.add(&r.stats); }
                    let pipe_name = format!("|- {}", name_of(ck));
                    print_row_with_files(&pipe_name, cf.len() as u64, &cstats, width, opts);
                }
                let mut total = v.stats.clone();
                for (_ck, cf) in &v.children {
                    for r in cf { total.add(&r.stats); }
                }
                print_no_files_row("(Total)", &total, width, opts);
            }
        }
    } else {
        for (k, v) in &ordered {
