        r.stats.blanks, r.stats.code, r.stats.comments, json_escape(&r.name)
    )
}

fn json_escape(s: &str) -> String {
    let mut r = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

fn stream_output(mode: &str, lang_stats: &BTreeMap<String, LanguageStats>) -> i32 {
    if mode == "simple" {
        println!("# language                                        path                                          lines         code       comments      blanks   ");
        println!("########## ################################################################################ ############ ############ ############ ############");
    }
