            if mode == "simple" {
                println!(
                    "{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}",
                    name, r.name, r.stats.lines(), r.stats.code, r.stats.comments, r.stats.blanks
                );
            } else {
                println!(
                    "{{\"language\":\"{}\",\"stats\":{{\"name\":\"{}\",\"stats\":{{\"blanks\":{},\"blobs\":{{}},\"code\":{},\"comments\":{}}}}}}}",
                    json_escape(&name), json_escape(&r.name), r.stats.blanks, r.stats.code, r.stats.comments
                );
            }
        }
    }
    0
}
