        Ok(t) => t,
        Err(_) => return None,
    };
    let cr = counter::count_text(&text, lang);
    let report = FileReport {
        name: path.display().to_string(),
        stats: cr.stats,
    };
    Some((lang.key.to_string(), report, cr.embedded))
}

const NUM_WIDTH: usize = 13;
const N_NUM_COLS: usize = 5;

fn term_width(opts: &Options) -> usize {
    let minimum = 81;
    let w = opts.columns.unwrap_or(81);
    if w < minimum { minimum } else { w }
}

fn bar(ch: &str, width: usize) -> String {
    ch.repeat(width)
}

fn print_table(opts: &Options, lang_stats: &BTreeMap<String, LanguageStats>) {
    let width = term_width(opts);
    let bar_heavy = bar("━", width);
    let bar_light = bar("─", width);
    println!("{}", bar_heavy);
    println!("{}", header_row(width));
    println!("{}", bar_heavy);

    let mut ordered: Vec<(String, LanguageStats)> = lang_stats.iter().map(|(k,v)| (k.clone(), v.clone())).collect();
    apply_sort(&mut ordered, opts);

    let has_any_children = ordered.iter().any(|(_, v)| !v.children.is_empty());
    let compact = opts.compact;
    if has_any_children && !compact {
        let mut first_group: Vec<&(String, LanguageStats)> = Vec::new();
        let mut second_group: Vec<&(String, LanguageStats)> = Vec::new();
        for kv in &ordered {
            if kv.1.children.is_empty() { first_group.push(kv); } else { second_group.push(kv); }
        }
        for (k, v) in &first_group {
            print_lang_row(k, v, width, opts);
            if opts.files {
                println!("{}", bar_light);
                for r in &v.reports {
                    print_file_row(&r.name, &r.stats, width, opts);
                }
                println!("{}", bar_light);
            }
        }
        if !second_group.is_empty() {
            println!("{}", bar_light);
            for (k, v) in &second_group {
                print_lang_row(k, v, width, opts);
                if opts.files {
                    println!("{}", bar_light);
                    for r in &v.reports {
                        print_file_row(&r.name, &r.stats, width, opts);
                    }
                    println!("{}", bar_light);
                }
                for (ck, cf) in &v.children {
                    let mut cstats = Stats::default();
                    for r in cf { cstats.add(&r.stats); }
                    let pipe_name = format!("|- {}", name_of(ck));
                    print_row_with_files(&pipe_name, cf.len() as u64, &cstats, width, opts);
                }
                let mut total = v.stats.clone();
                for (_ck, cf) in &v.children {
                    for r in cf { total.add(&r.stats); }
                }
                print_no_files_row("(Total)", &total, width, opts);
            }
        }
    } else {
        for (k, v) in &ordered {
            print_lang_row(k, v, width, opts);
            if opts.files {
                println!("{}", bar_light);
                for r in &v.reports {
                    print_file_row(&r.name, &r.stats, width, opts);
                }
                println!("{}", bar_light);
            }
        }
    }

    println!("{}", bar_heavy);
    let mut total = Stats::default();
    let mut total_files: u64 = 0;
    for (_k, v) in &ordered {
        total.add(&v.stats);
        total_files += v.files();
        for (_, cf) in &v.children {
            for r in cf { total.add(&r.stats); }
        }
    }
    print_row_with_files("Total", total_files, &total, width, opts);
    println!("{}", bar_heavy);
}

fn apply_sort(ordered: &mut Vec<(String, LanguageStats)>, opts: &Options) {
    ordered.sort_by(|a, b| {
        let an = name_of(&a.0);
        let bn = name_of(&b.0);
        an.cmp(&bn)
    });
    if let Some(col) = opts.sort.as_deref().or(opts.rsort.as_deref()) {
        ordered.sort_by(|a, b| {
            let av = column_val(col, &a.1);
            let bv = column_val(col, &b.1);
            bv.cmp(&av)
        });
    }
    if opts.rsort.is_some() {
        ordered.reverse();
    }
}

fn column_val(col: &str, s: &LanguageStats) -> u64 {
    let total = s.total_stats();
    match col {
        "files" => s.files(),
        "lines" => total.lines(),
        "code" => total.code,
        "comments" => total.comments,
        "blanks" => total.blanks,
        _ => 0,
    }
}

fn name_of(k: &str) -> String {
    if let Some(l) = lang_by_key(k) { return l.name.to_string(); }
    k.to_string()
}

fn header_row(width: usize) -> String {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut s = String::new();
    s.push(' ');
    s.push_str(&pad_right("Language", name_w - 1));
    s.push_str(&pad_left_width("Files", NUM_WIDTH));
    s.push_str(&pad_left_width("Lines", NUM_WIDTH));
    s.push_str(&pad_left_width("Code", NUM_WIDTH));
    s.push_str(&pad_left_width("Comments", NUM_WIDTH));
    s.push_str(&pad_left_width("Blanks", NUM_WIDTH));
    s
}

fn pad_right(s: &str, w: usize) -> String {
    let c: Vec<char> = s.chars().collect();
    if c.len() >= w { return s.to_string(); }
    let mut r = String::from(s);
    for _ in c.len()..w { r.push(' '); }
    r
}
fn pad_left_width(s: &str, w: usize) -> String {
    let n = s.chars().count();
    let mut r = String::new();
    if n < w { for _ in n..w { r.push(' '); } }
    r.push_str(s);
    r
}

fn format_num(n: u64, opts: &Options) -> String {
    numfmt::format(n, opts.num_format.as_deref())
}

fn print_lang_row(k: &str, v: &LanguageStats, width: usize, opts: &Options) {
    let name = name_of(k);
    let files = v.files();
    print_row_with_files(&name, files, &v.stats, width, opts);
}

fn print_row_with_files(name: &str, files: u64, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut out = String::new();
    out.push(' ');
    out.push_str(&pad_right(&truncate_to(name, name_w - 1), name_w - 1));
    out.push_str(&pad_left_width(&format_num(files, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn print_no_files_row(label: &str, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let mut out = String::new();
    out.push(' ');
    out.push_str(&pad_right(label, name_w - 1 + NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn print_file_row(name: &str, s: &Stats, width: usize, opts: &Options) {
    let cw = width - 1;
    let name_w = cw - NUM_WIDTH * N_NUM_COLS;
    let max_name_display = (name_w - 1) + NUM_WIDTH;
    let mut d = name.to_string();
    if d.chars().count() > max_name_display {
        let chars: Vec<char> = d.chars().collect();
        let start = chars.len() - (max_name_display - 1);
        d = format!("|{}", chars[start..].iter().collect::<String>());
    }
    let mut out = String::new();
    out.push(' ');
    out.push_str(&pad_right(&d, name_w - 1 + NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.lines(), opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.code, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.comments, opts), NUM_WIDTH));
    out.push_str(&pad_left_width(&format_num(s.blanks, opts), NUM_WIDTH));
    println!("{}", out);
}

fn truncate_to(s: &str, w: usize) -> String {
    let c: Vec<char> = s.chars().collect();
    if c.len() <= w { return s.to_string(); }
    c.iter().take(w).collect()
}

fn format_output(fmt: &str, lang_stats: &BTreeMap<String, LanguageStats>) -> i32 {
    if fmt == "json" {
        print!("{}", json_output(lang_stats));
        return 0;
    }
    eprintln!("error: format {} not compiled in", fmt);
    1
}

fn json_output(lang_stats: &BTreeMap<String, LanguageStats>) -> String {
    let mut s = String::new();
    s.push('{');
    let mut first = true;
    // Ordered keys same as BTreeMap (alphabetical by key, not name)
    // Accumulate total
    let mut total = LanguageStats::default();
    for (k, v) in lang_stats {
        if !first { s.push(','); } first = false;
        s.push('"'); s.push_str(&json_escape(&name_of(k))); s.push('"'); s.push(':');
        s.push_str(&json_lang_stats(v));
        total.stats.add(&v.stats);
        for r in &v.reports {
            total.children.entry(k.clone()).or_default().push(r.clone());
        }
        for (ck, cf) in &v.children {
            total.stats.add(&{
                let mut t = Stats::default();
                for r in cf { t.add(&r.stats); }
                t
            });
            for r in cf {
                total.children.entry(ck.clone()).or_default().push(r.clone());
            }
        }
    }
    if !first { s.push(','); }
    s.push_str("\"Total\":");
    s.push_str(&json_lang_stats_total(&total));
    s.push('}');
    s
}

fn json_lang_stats(v: &LanguageStats) -> String {
    let mut s = String::new();
    s.push('{');
    s.push_str(&format!("\"blanks\":{},\"code\":{},\"comments\":{}", v.stats.blanks, v.stats.code, v.stats.comments));
    s.push_str(",\"reports\":[");
    for (i, r) in v.reports.iter().enumerate() {
        if i > 0 { s.push(','); }
        s.push_str(&json_report(r));
    }
    s.push_str("],\"children\":{");
    let mut first = true;
    for (ck, cf) in &v.children {
        if !first { s.push(','); } first = false;
        s.push('"'); s.push_str(&json_escape(&name_of(ck))); s.push('"'); s.push(':'); s.push('[');
        for (i, r) in cf.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&json_report(r));
        }
        s.push(']');
    }
    s.push_str("},\"inaccurate\":false}");
    s
}

fn json_lang_stats_total(v: &LanguageStats) -> String {
    let mut s = String::new();
    s.push('{');
    s.push_str(&format!("\"blanks\":{},\"code\":{},\"comments\":{}", v.stats.blanks, v.stats.code, v.stats.comments));
    s.push_str(",\"reports\":[],\"children\":{");
    let mut first = true;
    for (ck, cf) in &v.children {
        if !first { s.push(','); } first = false;
        s.push('"'); s.push_str(&json_escape(&name_of(ck))); s.push('"'); s.push(':'); s.push('[');
        for (i, r) in cf.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&json_report(r));
        }
        s.push(']');
    }
    s.push_str("},\"inaccurate\":false}");
    s
}

fn json_report(r: &FileReport) -> String {
    format!(
        "{{\"stats\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{}}}},\"name\":\"{}\"}}",
        r.stats.blanks, r.stats.code, r.stats.comments, json_escape(&r.name)
    )
}

fn json_escape(s: &str) -> String {
    let mut r = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

fn stream_output(mode: &str, lang_stats: &BTreeMap<String, LanguageStats>) -> i32 {
    if mode == "simple" {
        println!("# language                                        path                                          lines         code       comments      blanks   ");
        println!("########## ################################################################################ ############ ############ ############ ############");
    }
    for (k, ls) in lang_stats {
        let name = name_of(k);
        for r in &ls.reports {
            if mode == "simple" {
                println!(
                    "{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}",
                    name, r.name, r.stats.lines(), r.stats.code, r.stats.comments, r.stats.blanks
                );
            } else {
                println!(
                    "{{\"language\":\"{}\",\"stats\":{{\"name\":\"{}\",\"stats\":{{\"blanks\":{},\"blobs\":{{}},\"code\":{},\"comments\":{}}}}}}}",
                    json_escape(&name), json_escape(&r.name), r.stats.blanks, r.stats.code, r.stats.comments
                );
            }
        }
    }
    0
}
