// Line counter for a single file
use crate::lang::{Lang, find_by_display_name_ci};
use std::collections::BTreeMap;

#[derive(Debug, Default, Clone)]
pub struct Stats {
    pub blanks: u64,
    pub code: u64,
    pub comments: u64,
}
impl Stats {
    pub fn lines(&self) -> u64 { self.blanks + self.code + self.comments }
    pub fn add(&mut self, other: &Stats) {
        self.blanks += other.blanks;
        self.code += other.code;
        self.comments += other.comments;
    }
}

pub struct CountResult {
    pub stats: Stats,
    pub embedded: BTreeMap<String, Stats>,
}

pub fn count_text(text: &str, lang: &Lang) -> CountResult {
    if lang.key == "Markdown" {
        return count_markdown(text);
    }
    let stats = count_plain(text, lang);
    CountResult { stats, embedded: BTreeMap::new() }
}

fn iter_lines(text: &str) -> Vec<&str> {
    let raw: Vec<&str> = text.split('\n').collect();
    if text.ends_with('\n') {
        let mut v = raw;
        v.pop();
        v
    } else {
        raw
    }
}

pub fn count_plain(text: &str, lang: &Lang) -> Stats {
    let mut s = Stats::default();
    if lang.all_non_blank_as_comments {
        for line in iter_lines(text) {
            let t = line.trim_end_matches('\r').trim();
            if t.is_empty() { s.blanks += 1; } else { s.comments += 1; }
        }
        return s;
    }

    let mut state = LineState::default();
    for mut line in iter_lines(text) {
        if line.ends_with('\r') { line = &line[..line.len()-1]; }
        let kind = classify(line, lang, &mut state);
        match kind {
            LineKind::Blank => s.blanks += 1,
            LineKind::Code => s.code += 1,
            LineKind::Comment => s.comments += 1,
        }
    }
    s
}

#[derive(Default, Debug, Clone)]
struct LineState {
    block_stack: Vec<&'static str>,
    doc_quote: Option<&'static str>,
    in_string: Option<&'static str>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LineKind { Blank, Code, Comment }

fn classify(line: &str, lang: &Lang, state: &mut LineState) -> LineKind {
    // If state is clean and line is empty => blank
    let trimmed = line.trim();
    if trimmed.is_empty()
        && state.block_stack.is_empty()
        && state.doc_quote.is_none()
        && state.in_string.is_none()
    {
        return LineKind::Blank;
    }
    // If we're inside a string/doc_quote/block comment with no content on this line,
    // tokei still counts it - in-string => code, in-block => comment, doc_quote => comment.
    // Otherwise parse char-by-char and determine had_code.
    // Starting state for the line: if we're inside a string, treat line as code by default.
    // If we're in a block comment or doc quote, treat as comment until they close, then re-evaluate.
    let bytes = trimmed.as_bytes();
    let mut i = 0;
    let mut had_code = state.in_string.is_some();
    let mut had_comment = state.block_stack.len() > 0 || state.doc_quote.is_some();
    while i < bytes.len() {
        // Doc quote
        if let Some(close) = state.doc_quote {
            if bytes_starts_with(bytes, i, close.as_bytes()) {
                i += close.len();
                state.doc_quote = None;
                had_comment = true;
                continue;
            }
            i += 1;
            had_comment = true;
            continue;
        }
        // Block comment
        if let Some(top_close) = state.block_stack.last().copied() {
            if lang.nested {
                let mut opened = false;
                for (open, close) in lang.multi_line {
                    if bytes_starts_with(bytes, i, open.as_bytes()) {
                        state.block_stack.push(close);
                        i += open.len();
                        opened = true;
                        break;
                    }
                }
                if opened { had_comment = true; continue; }
            }
            if bytes_starts_with(bytes, i, top_close.as_bytes()) {
                state.block_stack.pop();
                i += top_close.len();
                had_comment = true;
                continue;
            }
            i += 1;
            had_comment = true;
            continue;
        }
        // String
        if let Some(close) = state.in_string {
            if bytes[i] == b'\\' && i + 1 < bytes.len() {
                i += 2; had_code = true; continue;
            }
            if bytes_starts_with(bytes, i, close.as_bytes()) {
                i += close.len();
                state.in_string = None;
                had_code = true;
                continue;
            }
            i += 1;
            had_code = true;
            continue;
        }
        // Line comment
        for lc in lang.line_comments {
            if bytes_starts_with(bytes, i, lc.as_bytes()) {
                // Rest of line is comment; if had_code so far, line remains code
                if had_code { return LineKind::Code; }
                return LineKind::Comment;
            }
        }
        // Block start
        let mut opened = false;
        for (open, close) in lang.multi_line {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                state.block_stack.push(close);
                i += open.len();
                opened = true;
                break;
            }
        }
        if opened { had_comment = true; continue; }
        // Doc quote
        let mut dqopen = false;
        for (open, close) in lang.doc_quotes {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                if had_code {
                    state.in_string = Some(close);
                } else {
                    state.doc_quote = Some(close);
                    had_comment = true;
                }
                i += open.len();
                dqopen = true;
                break;
            }
        }
        if dqopen { continue; }
        // String start
        let mut stopen = false;
        for (open, close) in lang.quotes {
            if bytes_starts_with(bytes, i, open.as_bytes()) {
                state.in_string = Some(close);
                had_code = true;
                i += open.len();
                stopen = true;
                break;
            }
        }
        if stopen { continue; }
        if !bytes[i].is_ascii_whitespace() {
            had_code = true;
        }
        i += 1;
    }
    if had_code { LineKind::Code }
    else if had_comment { LineKind::Comment }
    else { LineKind::Blank }
}

fn bytes_starts_with(hay: &[u8], at: usize, needle: &[u8]) -> bool {
    if at + needle.len() > hay.len() { return false; }
    &hay[at..at+needle.len()] == needle
}

// ----- Markdown with embedded code blocks -----

pub fn count_markdown(text: &str) -> CountResult {
    let mut md = Stats::default();
    let mut embedded: BTreeMap<String, String> = BTreeMap::new();
    let lines = iter_lines(text);
    let mut i = 0;
    while i < lines.len() {
        let mut raw = lines[i];
        if raw.ends_with('\r') { raw = &raw[..raw.len()-1]; }
        let trimmed = raw.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            let fence = if trimmed.starts_with("```") { "```" } else { "~~~" };
            let lang_name: String = trimmed[fence.len()..].trim().chars()
                .take_while(|c| c.is_alphanumeric() || *c == '+' || *c == '-' || *c == '_').collect();
            md.comments += 1;
            i += 1;
            let mut body = String::new();
            let mut closed = false;
            while i < lines.len() {
                let mut body_raw = lines[i];
                if body_raw.ends_with('\r') { body_raw = &body_raw[..body_raw.len()-1]; }
                let btrim = body_raw.trim_start();
                if btrim.starts_with(fence) {
                    md.comments += 1;
                    i += 1;
                    closed = true;
                    break;
                }
                body.push_str(body_raw);
                body.push('\n');
                i += 1;
            }
            if !closed {
                for line in body.lines() {
                    if line.trim().is_empty() { md.blanks += 1; }
                    else { md.comments += 1; }
                }
            } else {
                if let Some(lang) = find_by_display_name_ci(&lang_name) {
                    let key = lang.key.to_string();
                    embedded.entry(key).or_default().push_str(&body);
                } else {
                    for line in body.lines() {
                        if line.trim().is_empty() { md.blanks += 1; }
                        else { md.comments += 1; }
                    }
                }
            }
            continue;
        }
        if raw.trim().is_empty() {
            md.blanks += 1;
        } else {
            md.comments += 1;
        }
        i += 1;
    }
    let mut emb_stats: BTreeMap<String, Stats> = BTreeMap::new();
    for (k, text) in embedded {
        let lang = crate::lang::LANGS.iter().find(|l| l.key == k).unwrap();
        let s = count_plain(&text, lang);
        emb_stats.insert(k, s);
    }
    CountResult { stats: md, embedded: emb_stats }
}
